window.kbPageData["views/entry/k-d0cc70f593898731"] = {"key":"entry/k-d0cc70f593898731","state":{"route":"entry/k-d0cc70f593898731"},"node":{"id":"k-d0cc70f593898731","mode":"k","title":"“让人民来监督政府”和“自我革命”","type":"原理与机制","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["party"],"主类":["原理与机制"],"出处性质":["机构注释"],"学科":["政治理论"],"来源主题":["党政制度与理论"],"资料类别":["非时政"]},"directorySummary":"3.“让人民来监督政府”和“自我革命”\n1945 年 7 月，在延安一孔窑洞里，面对黄炎培提出的如何跳出“其兴也勃焉，其\n亡也忽焉”的历史周期率的问题，毛泽东同志给出第一个答案：“让人民来监督政\n府”。以习近平同志为核心的党中央在新时代全面从严治党伟大实践中给出第二个答\n案：自我革命。\n习近平总书记…","sources":[{"id":"c16f4ec02a3b3033","label":"“让人民来监督政府”和“自我革命”","topic":"党政制度与理论","category":"非时政","text":"3.“让人民来监督政府”和“自我革命”\n1945 年 7 月，在延安一孔窑洞里，面对黄炎培提出的如何跳出“其兴也勃焉，其\n亡也忽焉”的历史周期率的问题，毛泽东同志给出第一个答案：“让人民来监督政\n府”。以习近平同志为核心的党中央在新时代全面从严治党伟大实践中给出第二个答\n案：自我革命。\n习近平总书记强调，一百年来，党外靠发展人民民主、接受人民监督，内靠全面\n从严治党、推进自我革命，勇于坚持真理、修正错误，勇于刀刃向内、刮骨疗毒，保\n证了党长盛不衰、不断发展壮大，这一重要论述深刻揭示了跳出历史周期率两个答案\n的相互关系。自我监督和人民监督相辅相成、相互促进，体现了内因和外因关系的深\n刻辩证法，两者都源于党的初心使命。\n——《中央纪委国家监委网站》","source":{"doc":"41195a191a57c1c36332","first":7,"last":7,"page":7,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"party","title":"党的建设与自我革命"}],"units":{"k-d0cc70f593898731":[]}};
